    static Set<String> paths() { return RULES.stream().map(Rule::path).collect(java.util.stream.Collectors.toSet()); }
    static boolean covered(BizEndpointSource.Endpoint endpoint) {
        String key = endpoint.method().owner() + "#" + endpoint.method().name();
        return RULES.stream().anyMatch(r -> r.path().equals(endpoint.path()) && r.method().equals(key));
    }
    static boolean authenticated(BizEndpointSource.Method method) {
        return BizEndpointSource.authorizationRequires(method.annotations().get("PreAuthorize"), "managementAccess", Set.of("authenticated"));
    }
    static boolean methodMatches(BizEndpointSource.Method method, List<String> calls) {
        return calls.stream().allMatch(method::calls);
    }
    static void verify(Path root, List<BizEndpointSource.Endpoint> endpoints) throws IOException {
        for (var endpoint : endpoints) {
            if (paths().contains(endpoint.path()) && !covered(endpoint)) {
                throw new AssertionError("Unregistered resource handler: " + endpoint.path() + " "
                        + endpoint.method().owner() + "#" + endpoint.method().name());
            }
        }
        for (Rule rule : RULES) {
            var matches = endpoints.stream().filter(e -> e.path().equals(rule.path())
                    && (e.method().owner() + "#" + e.method().name()).equals(rule.method())).toList();
            if (matches.isEmpty() || matches.stream().anyMatch(e -> !authenticated(e.method())
                    || !methodMatches(e.method(), rule.calls()))) {
                throw new AssertionError("Missing actor/resource authorization: " + rule.method() + " " + rule.path());
            }
            for (String proof : rule.evidence()) verifyEvidence(root, proof, new HashSet<>());
        }
        verifyEvidence(root, "ManagementAccess#authenticated", new HashSet<>());
        verifyEvidence(root, "ManagementAccess#actor", new HashSet<>());
        verifyEvidence(root, "ManagementScopeServiceImpl#require", new HashSet<>());
        verifyEvidence(root, "ManagementScopeServiceImpl#resolve", new HashSet<>());
        verifyEvidence(root, "ManagementScopeServiceImpl#can", new HashSet<>());
        verifyEvidence(root, "ManagementScopeServiceImpl#ownerAccounts", new HashSet<>());
    }
    private static void verifyEvidence(Path root, String key, Set<String> visited) throws IOException {
        if (!visited.add(key)) return;
        Evidence evidence = EVIDENCE.get(key);
        if (evidence == null) throw new AssertionError("Unknown resource authorization evidence: " + key);
        var methods = BizEndpointSource.read(root.resolve(evidence.source())).methods().stream()
                .filter(m -> (m.owner() + "#" + m.name()).equals(evidence.method())).toList();
        if (methods.size() != 1 || !methodMatches(methods.getFirst(), evidence.calls())) {
            throw new AssertionError("Resource guard changed: " + evidence.source() + " " + key);
        }
        for (String dependency : evidence.dependencies()) verifyEvidence(root, dependency, visited);
    }
